const source = $('Reload Presentation Data').isExecuted
  ? $('Reload Presentation Data').first().json
  : $('Get Presentation Data').first().json;
const presentationId = $input.first().json.id;

if (!presentationId) {
  throw new Error('Copied presentation ID is missing');
}

const m = typeof source.metrics_snapshot === 'string'
  ? JSON.parse(source.metrics_snapshot)
  : source.metrics_snapshot;

// Normalize the AI-generated Markdown.
const report = String(source.report_markdown || '')
  .replace(/\\n/g, '\n');

// Extract a numbered report section.
function section(number) {
  const heading = new RegExp(
    `^#{1,4}\\s*${number}\\.\\s*[^\\n]*$`, 'mi'
  );
  const match = heading.exec(report);

  if (!match) {
    throw new Error(`Report section ${number} not found`);
  }

  const remaining = report.slice(
    match.index + match[0].length
  );

  return remaining
    .split(/\n(?=#{1,4}\s*\d+\.\s)/)[0]
    .trim()
    .replace(/\*\*/g, '');
}

// Format numbers safely.
function num(key) {
  const value = Number(m[key]);

  if (!Number.isFinite(value)) {
    throw new Error(`Invalid metric: ${key}`);
  }

  return value;
}

function integer(key) {
  return num(key).toLocaleString('en-US');
}

function usd(key) {
  return '$' + num(key).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function change(key, suffix = '%') {
  const value = num(key);

  return (value > 0 ? '+' : '') +
    value.toFixed(2) + suffix;
}


function movement(key) {
  const value = num(key);

  if (value === 0) return 'remained unchanged';

  return `${value < 0 ? 'fell' : 'rose'} ${Math.abs(value).toFixed(2)}%`;
}

function shortFindings() {
  const conversionChange = num('conversion_change_pp');

  return [
    `Revenue ${movement('revenue_wow_pct')}; purchases ${movement('purchases_wow_pct')}.`,

    `Revenue per purchase ${movement('revenue_per_purchase_wow_pct')} (${usd('prev_revenue_per_purchase_usd')} to ${usd('revenue_per_purchase_usd')}).`,

    `Conversion rate changed by ${conversionChange > 0 ? '+' : ''}${conversionChange.toFixed(2)} pp to ${num('conversion_rate_pct').toFixed(2)}%.`
  ].join('\n\n');
}

function shortRecommendations() {
  const recommendations = section(4);

  const titles = [...recommendations.matchAll(
    /(?:^|\n)\s*(?:\d+[.)]|[-*+])\s*([^:\n]{4,90}):/g
  )]
    .map(match => match[1].trim())
    .slice(0, 2);

  if (titles.length === 2) {
    return titles
      .map((title, index) => `${index + 1}. Investigate ${title.toLowerCase()}.`)
      .join('\n\n');
  }

  const questions = [...recommendations.matchAll(
    /(?:^|\n)\s*(?:\d+[.)]|[-*+])\s*([^\n?]+\?)\s*(?=\n|$)/g
  )]
    .map(match => match[1].trim())
    .slice(0, 2);

  if (questions.length !== 2) {
    throw new Error('Could not extract two investigation titles');
  }

  return questions
    .map((question, index) => `${index + 1}. ${question}`)
    .join('\n\n');
}


// Map all template placeholders.
const fields = {
  REPORTING_WEEK:
    `${source.week_start} to ${source.week_end}`,

  EXECUTIVE_SUMMARY: section(1),

  USERS: integer('total_users'),
  USERS_WOW: change('users_wow_pct'),

  PURCHASES: integer('purchases'),
  PURCHASES_WOW: change('purchases_wow_pct'),

  REVENUE: usd('revenue_usd'),
  REVENUE_WOW: change('revenue_wow_pct'),

  CONVERSION_RATE:
    num('conversion_rate_pct').toFixed(2) + '%',

  CONVERSION_CHANGE_PP:
    change('conversion_change_pp', ' pp'),

  REVENUE_PER_PURCHASE:
    usd('revenue_per_purchase_usd'),

  RPP_WOW:
    change('revenue_per_purchase_wow_pct'),

  KEY_FINDINGS: shortFindings(),
  RECOMMENDATIONS: shortRecommendations()
};

// Build Google Slides replacement requests.
const requests = Object.entries(fields).map(
  ([name, value]) => ({
    replaceAllText: {
      containsText: {
        text: `{{${name}}}`,
        matchCase: true
      },
      replaceText: String(value)
    }
  })
);

return [{
  json: {
    presentationId,
    placeholderCount: requests.length,
    requests
  }
}];

